/**
 * Returns the name to show for a user: their name, or their email if the
 * name is empty, or 'Anonymous' if there is no user.
 * @param {{name?: string, email?: string} | null} user
 * @returns {string}
 */
export function displayName(user) {
  if (!user) return 'Anonymous';
  return user.name || user.email;
}

